from taf.ul.ettf.pdml_parser.parser import PdmlParserError


class PacketExtractor(object):
    def __init__(self, pdml_parser):
        self._pdml_parser = pdml_parser
        self._data = ''

    def data_received(self, chunk):
        self._data += str(chunk)

    def extract(self):
        for packet in self._extract_raw_packets():
            try:
                yield self._parse_packet(packet)
            except PdmlParserError:
                continue

    def _extract_raw_packets(self):
        packet_start, packet_end = '<packet>', '</packet>'

        while True:
            try:
                beg_idx = self._data.index(packet_start)
                end_idx = self._data.index(
                    packet_end, beg_idx) + len(packet_end)
            except ValueError:
                break
            else:
                packet = self._data[beg_idx:end_idx]
                self._data = self._data[end_idx:]
                yield packet

    def _parse_packet(self, packet):
        pdml = """<?xml version="1.0"?><pdml>%s</pdml>""" % packet
        try:
            return self._pdml_parser(pdml)[0]
        except BaseException:
            raise PdmlParserError('Parsing packet failed')
